ALTER POLICY "tenant" ON "board_favorites" TO public USING ("board_favorites"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("board_favorites"."org_id" is not null or exists (select 1 from "boards" where "boards"."id" = "board_favorites"."board_id"))) WITH CHECK ("board_favorites"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("board_favorites"."org_id" is not null or exists (select 1 from "boards" where "boards"."id" = "board_favorites"."board_id")));--> statement-breakpoint
ALTER POLICY "tenant" ON "board_members" TO public USING ("board_members"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("board_members"."org_id" is not null or current_setting('app.membership_lookup', true) = 'on' or exists (select 1 from "boards" where "boards"."id" = "board_members"."board_id"))) WITH CHECK ("board_members"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("board_members"."org_id" is not null or current_setting('app.membership_lookup', true) = 'on' or exists (select 1 from "boards" where "boards"."id" = "board_members"."board_id")));--> statement-breakpoint
ALTER POLICY "tenant" ON "boards" TO public USING ("boards"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("boards"."org_id" is not null or "boards"."owner_email" = nullif(current_setting('app.email', true), '') or "boards"."id" = any((select app_member_board_ids())::uuid[]))) WITH CHECK ("boards"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("boards"."org_id" is not null or "boards"."owner_email" = nullif(current_setting('app.email', true), '') or "boards"."id" = any((select app_member_board_ids())::uuid[])));--> statement-breakpoint
