ALTER POLICY "tenant" ON "task_assignees" TO public USING ("task_assignees"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("task_assignees"."org_id" is not null or exists (select 1 from "tasks" where "tasks"."id" = "task_assignees"."task_id"))) WITH CHECK ("task_assignees"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("task_assignees"."org_id" is not null or exists (select 1 from "tasks" where "tasks"."id" = "task_assignees"."task_id")));--> statement-breakpoint
ALTER POLICY "tenant" ON "tasks" TO public USING ("tasks"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("tasks"."org_id" is not null or exists (select 1 from "boards" where "boards"."id" = "tasks"."board_id"))) WITH CHECK ("tasks"."org_id" is not distinct from nullif(current_setting('app.org_id', true), '') and ("tasks"."org_id" is not null or exists (select 1 from "boards" where "boards"."id" = "tasks"."board_id")));